class Solution {
    public int differenceOfSums(int n, int m) {
        int num1 = 0;
        int num2 = 0;
        for (int value = 1; value <= n; value++) {
            if (value % m == 0) {
                num2 += value;
            } else {
                num1 += value;
            }
        }
        return num1 - num2;
    }
}

class Solution {
    public int differenceOfSums(int n, int m) {
        int answer = 0;
        for (int value = 1; value <= n; value++) {
            if (value % m == 0) {
                answer -= value;
            } else {
                answer += value;
            }
        }
        return answer;
    }
}

class Solution {
    public int differenceOfSums(int n, int m) {
        int total = n * (n + 1) / 2;
        int k = n / m;
        int divisibleSum = m * k * (k + 1) / 2;
        return total - 2 * divisibleSum;
    }
}

class Solution {
    public int differenceOfSums(int n, int m) {
        int answer = n * (n + 1) / 2;
        for (int value = m; value <= n; value += m) {
            answer -= 2 * value;
        }
        return answer;
    }
}
